Ltac sd_retlit := lazymatch goal with |- context [ret_pc (Z_to_bv 64 ?n)] =>
  replace (ret_pc (Z_to_bv 64 n)) with (Z_to_bv 64 n) by (symmetry; apply ret_pc_even; [lia| reflexivity]) end.

Section CANSEC1. Context {rc : runConstT}.

Lemma artcells_munchD : forall W m m', artcells m -> munch W m m' -> wmono bsegs m m' -> aboveD 0x150340 W -> artcells m'.
Proof.
  intros W m m' H MU WM AB.
  assert (T : forall X cs, rw_cells bsegs m X cs -> aboveD (X + Z.of_nat (cells_size cs)) W -> rw_cells bsegs m' X cs).
  { intros X cs HX AX. eapply rw_cells_transport; [exact HX| exact MU| exact WM|]. apply disjoint_of_aboveD; [exact AX| lia]. }
  unfold artcells in H |- *.
  repeat match goal with Hc : _ /\ _ |- _ => destruct Hc end.
  repeat match goal with |- _ /\ _ => split end;
    (eapply T; [eassumption | eapply aboveD_mono; [exact AB | cbn; lia]]).
Qed.


Section SDEC.
  Variables (RNG : footprint) (Q : machine_state -> Prop) (m0 : amem) (SPV FF DST dcap S0 DT lo RLO RHI : Z) (bs : list Z)
            (d : dtable) (gp tp : word) (FR : bvmap 5 word) (fc : bv 32) (j48 jd : list byte).
  Notation SP1 := (SPAf SPV).
  Notation tl := (dt_tableLog d).
  Hypothesis FC32 : rw_cells bsegs m0 (SP1 + 32) [C8 (Z_to_bv 64 FF); C8 (Z_to_bv 64 FF); C8 (Z_to_bv 64 DST); C8 (Z_to_bv 64 2147450880)].
  Hypothesis FOBJ : rw_cells bsegs m0 (SP1 + 80) [CB 72 j48].
  Hypothesis STK : stk bsegs m0 lo SP1.
  Hypothesis BOT : ATOP + 4096 <= lo.
  Hypothesis LO : lo <= SP1 - DEC_STACK.
  Hypothesis SP16 : SPV mod 16 = 0.
  Hypothesis SPH : SPV + 16 <= 2^47.
  Hypothesis ZOBJ : zshadow m0 (SP1 + 80) 72.
  Hypothesis SHC : shclean m0 (SP1 + 112) (SP1 + 152) RLO RHI.
  Hypothesis RRH : rng RNG (shad RLO) (shad RHI - shad RLO).
  Hypothesis RO : rng RNG (SP1 + 80) 72.
  Hypothesis ROs : rng RNG (shad (SP1 + 80)) 9.
  Hypothesis RO32 : rng RNG (SP1 + 32) 32.
  Hypothesis HTL : 5 <= tl <= 12.
  Hypothesis HCELLS : zlen (dt_cells d) = 2^tl.
  Hypothesis HCOK : RF_huf_fdw_sm.cells_ok tl (dt_cells d).
  Hypothesis FM : dt_fastMode d = 0.
  Hypothesis DTH : rw_cells bsegs m0 DT [C2 (Z_to_bv 64 tl); C2 (Z_to_bv 64 0)].
  Hypothesis TBB : bytes_at bsegs m0 (DT + 4) (concat (map fse_cell_bytes (dt_cells d))).
  Hypothesis HDT : ablk DT (DT + 4 + 4 * 2^tl).
  Hypothesis DT4 : DT mod 4 = 0.
  Hypothesis ZDT : zshadow m0 DT (4 + 4 * 2^tl).
  Hypothesis RDT : rng RNG DT (4 + 4 * 2^tl).
  Hypothesis RDTs : rng RNG (shad DT) (nshad (4 + 4 * 2^tl + DT mod 8)).
  Hypothesis SRC : bytes_at bsegs m0 S0 (map (Z_to_bv 8) bs).
  Hypothesis BY : Forall (fun c => 0 <= c < 256) bs.
  Hypothesis NS : zlen bs <= 65536.
  Hypothesis HS0 : ablk S0 (S0 + zlen bs).
  Hypothesis S8 : S0 + 8 <= 2^47.
  Hypothesis S16 : 16 <= S0.
  Hypothesis USRC : unpoisoned m0 S0 (S0 + zlen bs).
  Hypothesis RS : rng RNG S0 (zlen bs).
  Hypothesis RSs : rng RNG (shad S0) (nshad (zlen bs + S0 mod 8)).
  Hypothesis RESOK : dres_ok (decompress_usingDTable bs d dcap false).
  Hypothesis OUTA : u8arr bsegs m0 DST jd.
  Hypothesis LJD : zlen jd = dcap.
  Hypothesis DC : 0 <= dcap <= 255.
  Hypothesis HDST : ablk DST (DST + dcap).
  Hypothesis DST3 : 3 <= DST.
  Hypothesis ZDST : zshadow m0 DST dcap.
  Hypothesis RDST : rng RNG DST dcap.
  Hypothesis RDSTs : rng RNG (shad DST) (nshad (dcap + DST mod 8)).
  Hypothesis DJ2 : DST + dcap <= S0 \/ S0 + zlen bs <= DST.
  Hypothesis DJ1 : DST + dcap <= DT \/ DT + 4 + 4 * 2^tl <= DST.
  Hypothesis DJ3 : S0 + zlen bs <= DT \/ DT + 4 + 4 * 2^tl <= S0.
  Hypothesis MI : mem_inv bsegs m0.
  Hypothesis RTC : artcells m0.
  Hypothesis ZMK : zshadow m0 ABIT_MASK 128.
  Hypothesis RSTK : rng RNG lo (SP1 - lo).
  Hypothesis RI : rng_aimg RNG.
  Hypothesis RISH : rng_aimg_sh RNG.
  Notation W0 := [(lo, SP1); (SP1 + 80, SP1 + 152); (DST, DST + dcap)].
  Hypothesis K : forall m1 rv (j48' : list byte) (y1 y5 y6 y7 y11 y12 y13 y14 y15 y16 y17 y19 y20 y21 y22 y23 y24 y25 y26 y27 y28 y29 y30 y31 : word),
       munch W0 m0 m1 -> wmono bsegs m0 m1 ->
       mem_inv bsegs m1 -> stk bsegs m1 lo SP1 -> rw_cells bsegs m1 (SP1 + 80) [CB 72 j48'] ->
       rw_cells bsegs m1 (SP1 + 32) [C8 (Z_to_bv 64 FF); C8 (Z_to_bv 64 FF); C8 (Z_to_bv 64 DST); C8 (Z_to_bv 64 2147450880)] ->
       dresA DST dcap (decompress_usingDTable bs d dcap false) m1 rv -> 0 <= rv < 2^64 ->
       evtF bsegs RNG Q
         (MS (mkR y1 (Z_to_bv 64 SP1) gp tp y5 y6 y7 (Z_to_bv 64 SPV) (Z_to_bv 64 SP1) (Z_to_bv 64 rv)
                  y11 y12 y13 y14 y15 y16 y17 (Z_to_bv 64 (Z.shiftr FF 3 + 2147450880)) y19
                  y20 y21 y22 y23 y24 y25 y26 y27 y28 y29 y30 y31)
             FR (Z_to_bv 64 0x98318) fc None m1 (seg_rom bsegs)).

  (* [comment removed for export] *)
  Lemma sdA_bit : forall (x1 x5 x6 x7 x10 x11 x13 x14 x15 x16 x17 x22 x23 x24 x25 x28 x29 x30 x31 : word),
    (forall d0 jp m1 (ra t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 : word),
       init_dstream bs = Ok d0 -> bd_zero d0 = false ->
       munch [(SP1 - ABIT_INIT_STACK, SP1); (SP1 + 112, SP1 + 112 + 40)] m0 m1 -> wmono bsegs m0 m1 -> mem_inv bsegs m1 ->
       stk bsegs m1 lo SP1 -> bytes_at bsegs m1 S0 (map (Z_to_bv 8) bs) -> rw_cells bsegs m1 (SP1 + 112) (bitdz_cellsA S0 d0 jp) ->
       evtF bsegs RNG Q
         (MS (mkR ra (Z_to_bv 64 SP1) gp tp t0 t1 t2 (Z_to_bv 64 SPV) (Z_to_bv 64 SP1) (Z_to_bv 64 (zlen bs))
                  a1 a2 a3 a4 a5 a6 a7 (Z_to_bv 64 (Z.shiftr FF 3 + 2147450880))
                  (Z_to_bv 64 (DST + dcap - 3)) (Z_to_bv 64 DT) (Z_to_bv 64 (DST + dcap)) x22 x23 x24 x25
                  (Z_to_bv 64 S0) (Z_to_bv 64 2147450880) t3 t4 t5 t6)
             FR (Z_to_bv 64 0x98678) fc None m1 (seg_rom bsegs))) ->
    evtF bsegs RNG Q
      (MS (mkR x1 (Z_to_bv 64 SP1) gp tp x5 x6 x7 (Z_to_bv 64 SPV) (Z_to_bv 64 SP1) x10
               x11 (Z_to_bv 64 (zlen bs)) x13 x14 x15 x16 x17 (Z_to_bv 64 (Z.shiftr FF 3 + 2147450880))
               (Z_to_bv 64 (DST + dcap - 3)) (Z_to_bv 64 DT) (Z_to_bv 64 (DST + dcap)) x22 x23 x24 x25
               (Z_to_bv 64 S0) (Z_to_bv 64 2147450880) x28 x29 x30 x31)
          FR (Z_to_bv 64 0x98664) fc None m0 (seg_rom bsegs)).
  Proof.
    intros x1 x5 x6 x7 x10 x11 x13 x14 x15 x16 x17 x22 x23 x24 x25 x28 x29 x30 x31 KOK.
    pose proof (spaf_props SPV SP16) as (SPAB & SPA32). pose proof LO as LO'. unfold DEC_STACK in LO'.
    zstep. zstep. zstep.
    eapply evtF_cut.
    { eapply bit_init_proofA;
        rewrite ?Z_to_bv_unsigned; unfold bv_wrap, bv_modulus, ABIT_INIT_STACK; cbn [Z.of_N];
        rewrite ?(Z.mod_small (SPAf SPV)) by lia;
        first [ reflexivity | lia | exact SRC | exact BY | exact STK | exact MI | exact RTC | exact RI
              | (intros _; split; [exact HS0 | lia]) | (intros _; split; [exact RS | exact RSs])
              | exact (shclean_sub _ _ _ _ _ _ _ SHC ltac:(lia) ltac:(lia) ltac:(lia)) | exact RRH
              | exact (rng_sub' _ _ _ _ _ RO ltac:(lia)) | (eapply rng_sub'; [exact RSTK| lia]) | exact USRC
              | (replace (SPAf SPV + 112 + 40) with (SPAf SPV + 152) by lia; exact SHC)
              | (eapply rng_sub; [exact RO | lia | lia])
              | (eapply rng_sub; [exact ROs | |]; rewrite !shad_div; Z.div_mod_to_equations; lia)
              | (pose proof (rw_cells_split_CB _ _ _ [] 72 j48 [] [32%nat; 40%nat] FOBJ eq_refl) as FO2; cbn [app mk_CB_cells] in FO2;
                 pose proof (rw_cells_mid _ _ _ [CB 32 (firstn 32 j48)] (CB 40 (firstn 40 (skipn 32 j48))) [] FO2) as FO3;
                 cbn [cells_size csize Nat.add] in FO3;
                 replace (SPAf SPV + 80 + Z.of_nat 32) with (SPAf SPV + 112) in FO3 by lia; exact FO3) ]. }
    intros ms' (t0 & t1 & t2 & a1 & a2 & a3 & a4 & a5 & a6 & a7 & t3 & t4 & t5 & t6 & ret & m1 & -> & MU & WM & MI1 & STK1 & SRC1 & IDR).
    rewrite unsigned_lit in MU, STK1 by lia.
    sd_retlit.
    destruct (init_dstream bs) as [d0|e| |] eqn:EI; try contradiction.
    - destruct IDR as (-> & BZ & jp & CELLS). zstep. zstep.
      replace (bv_ltu (Z_to_bv 64 (-120)) (Z_to_bv 64 (zlen bs))) with false by
        (symmetry; rewrite bv_ltu_Z, !Z_to_bv_unsigned; unfold bv_wrap, bv_modulus; cbn [Z.of_N]; apply Z.ltb_ge;
         assert (0 <= zlen bs) by (change (zlen bs) with (Z.of_nat (length bs)); lia); Z.div_mod_to_equations; lia).
      cbv iota.
      eapply KOK; first [ reflexivity | eassumption ].
    - destruct IDR as (-> & j' & CELLS). zstep. zstep.
      pose proof (RF_huf_x4s04.init_dstream_err_range bs e BY EI) as ER.
      replace (bv_ltu (Z_to_bv 64 (-120)) (Z_to_bv 64 (- e))) with true by
        (symmetry; rewrite bv_ltu_Z, !Z_to_bv_unsigned; unfold bv_wrap, bv_modulus; cbn [Z.of_N]; apply Z.ltb_lt;
         Z.div_mod_to_equations; lia).
      cbv iota.
      replace (Z_to_bv 64 (- e)) with (Z_to_bv 64 (2^64 - e)) by (apply Z_to_bv_eqm; Z.div_mod_to_equations; lia).
      assert (FM80 : rw_cells bsegs m1 (SP1 + 80) [CB 72 (cells_bytes [CB 32 (firstn 32 j48); CB 40 j'])]).
      { pose proof (rw_cells_split_CB _ _ _ [] 72 j48 [] [32%nat; 40%nat] FOBJ eq_refl) as FO2; cbn [app mk_CB_cells] in FO2.
        pose proof (rw_cells_mid _ _ _ [] _ _ FO2) as FO3. cbn [cells_size csize Z.of_nat] in FO3. rewrite Z.add_0_r in FO3.
        eapply rw_cells_transport in FO3; [| exact MU | exact WM | cbn; unfold ABIT_INIT_STACK; lia].
        pose proof (rw_cells_cat _ _ _ _ _ _ FO3 CELLS ltac:(cbn; lia)) as FC.
        assert (FC' : rw_cells bsegs m1 (SP1 + 80) ([] ++ [CB 32 (firstn 32 j48); CB 40 j'] ++ [])) by exact FC.
        exact (rw_cells_merge _ _ _ _ _ _ FC'). }
      assert (DE : decompress_usingDTable bs d dcap false = Err e) by (unfold decompress_usingDTable; rewrite EI; reflexivity).
      eapply (K m1 (2^64 - e)).
      + eapply munch_weaken; [| exact MU]. unfold sub_fp; intros x Hx; cbn [outside] in Hx |- *. unfold ABIT_INIT_STACK.
        destruct Hx as (H1 & H2 & _). repeat split; lia.
      + exact WM.
      + exact MI1.
      + exact STK1.
      + exact FM80.
      + eapply rw_cells_transport; [exact FC32 | exact MU | exact WM | cbn; unfold ABIT_INIT_STACK; lia].
      + rewrite DE. unfold dresA. split; [reflexivity | lia].
      + lia.
  Qed.

  Ltac sd_ids_side MU WM :=
    rewrite ?Z_to_bv_unsigned; unfold bv_wrap, bv_modulus, AFSE_INIT_STACK; cbn [Z.of_N];
    rewrite ?(Z.mod_small (SPAf SPV)) by lia;
    first [ reflexivity | lia | exact BY | exact RI | exact RISH | exact RS | exact RSs | exact HS0
          | (eapply rw_cells_transport; [exact DTH | exact MU | exact WM | cbn; unfold ABIT_INIT_STACK; lia])
          | (eapply ablk_sub; [exact HDT | lia | lia])
          | (eapply artcells_munchD; [exact RTC | exact MU | exact WM | cbn; unfold ABIT_INIT_STACK; lia])
          | (eapply zshadow_munch; [eapply (zshadow_sub _ _ _ _ _ ZOBJ); lia | exact MU | intros a Ha;
               pose proof (shad_in_band a ltac:(lia)); cbn [outside]; unfold ABIT_INIT_STACK; lia | lia | lia])
          | (eapply zshadow_munch; [eapply (zshadow_sub _ _ _ _ _ ZDT); lia | exact MU | intros a Ha;
               pose proof (shad_in_band a ltac:(lia)); cbn [outside]; unfold ABIT_INIT_STACK; lia | lia | lia])
          | (eapply zshadow_munch; [exact ZMK | exact MU | intros a Ha;
               pose proof (shad_in_band a ltac:(unfold ABIT_MASK in *; lia)); cbn [outside]; unfold ABIT_INIT_STACK; lia
             | unfold ABIT_MASK; lia | unfold ABIT_MASK; lia])
          | (eapply unpoisoned_munch; [exact USRC | exact MU | cbn; unfold ABIT_INIT_STACK;
               pose proof (shad_in_band S0 ltac:(lia)); pose proof (shad_in_band (S0 + zlen bs - 1) ltac:(lia)); lia])
          | (eapply rng_sub; [exact RO | lia | lia]) | (eapply rng_sub; [exact RDT | lia | lia])
          | (eapply rng_sub; [exact RSTK | lia | lia])
          | (eapply rng_sub; [exact ROs | |]; rewrite !shad_div; Z.div_mod_to_equations; lia)
          | (eapply rng_sub; [exact RDTs | lia |]; rewrite nshad_div; Z.div_mod_to_equations; lia) ].

  (* [comment removed for export] *)
  Lemma sdA_ids : forall d0 jp m1 (ra t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 x22 x23 x24 x25 t3 t4 t5 t6 : word),
       init_dstream bs = Ok d0 -> bd_zero d0 = false ->
       munch [(SP1 - ABIT_INIT_STACK, SP1); (SP1 + 112, SP1 + 112 + 40)] m0 m1 -> wmono bsegs m0 m1 -> mem_inv bsegs m1 ->
       stk bsegs m1 lo SP1 -> bytes_at bsegs m1 S0 (map (Z_to_bv 8) bs) -> rw_cells bsegs m1 (SP1 + 112) (bitdz_cellsA S0 d0 jp) ->
       (forall m3 jp3 v1 v2 st1 st2 d1 d1r d2 d2r (ra t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 : word),
          read_bits d0 tl = Ok (v1, d1) -> reload_dstream bs d1 = Ok (st1, d1r) ->
          read_bits d1r tl = Ok (v2, d2) -> reload_dstream bs d2 = Ok (st2, d2r) ->
          munch W0 m0 m3 -> wmono bsegs m0 m3 -> mem_inv bsegs m3 -> stk bsegs m3 lo SP1 ->
          bytes_at bsegs m3 S0 (map (Z_to_bv 8) bs) ->
          rw_cells bsegs m3 (SP1 + 80) [C8 (Z_to_bv 64 v2); C8 (Z_to_bv 64 (DT + 4))] ->
          rw_cells bsegs m3 (SP1 + 96) [C8 (Z_to_bv 64 v1); C8 (Z_to_bv 64 (DT + 4))] ->
          rw_cells bsegs m3 (SP1 + 112) (bitdz_cellsA S0 d2r jp3) ->
          evtF bsegs RNG Q
            (MS (mkR ra (Z_to_bv 64 SP1) gp tp t0 t1 t2 (Z_to_bv 64 SPV) (Z_to_bv 64 SP1) a0
                     a1 a2 a3 a4 a5 a6 a7 (Z_to_bv 64 (Z.shiftr FF 3 + 2147450880))
                     (Z_to_bv 64 (DST + dcap - 3)) (Z_to_bv 64 DT) (Z_to_bv 64 (DST + dcap)) x22 x23 x24 x25
                     (Z_to_bv 64 S0) (Z_to_bv 64 2147450880) t3 t4 t5 t6)
                FR (Z_to_bv 64 0x98698) fc None m3 (seg_rom bsegs))) ->
       evtF bsegs RNG Q
         (MS (mkR ra (Z_to_bv 64 SP1) gp tp t0 t1 t2 (Z_to_bv 64 SPV) (Z_to_bv 64 SP1) (Z_to_bv 64 (zlen bs))
                  a1 a2 a3 a4 a5 a6 a7 (Z_to_bv 64 (Z.shiftr FF 3 + 2147450880))
                  (Z_to_bv 64 (DST + dcap - 3)) (Z_to_bv 64 DT) (Z_to_bv 64 (DST + dcap)) x22 x23 x24 x25
                  (Z_to_bv 64 S0) (Z_to_bv 64 2147450880) t3 t4 t5 t6)
             FR (Z_to_bv 64 0x98678) fc None m1 (seg_rom bsegs)).
  Proof.
    intros d0 jp m1 ra t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 x22 x23 x24 x25 t3 t4 t5 t6 EI BZ MU1 WM1 MI1 STK1 SRC1 CELLS KIDS.
    pose proof (spaf_props SPV SP16) as (SPAB & SPA32). pose proof LO as LO'. unfold DEC_STACK in LO'.
    pose proof (ablk_lin _ _ HDT) as LDT. pose proof (ablk_lin _ _ HS0) as LS0. pose proof (ablk_lin _ _ HDST) as LDS.
    pose proof ATOP_range as ATR. unfold ATOP_MIN, ATOP_MAX in ATR. assert (PT : 0 < 2^tl) by (apply Z.pow_pos_nonneg; lia).
    assert (ZL : 0 <= zlen bs) by (change (zlen bs) with (Z.of_nat (length bs)); lia).
    pose proof (RF_huf_fdw_pure.init_facts bs d0 BY EI) as (BOK0 & B64 & _).
    destruct (read_bits_okD d0 tl ltac:(lia)) as (v1 & d1 & RB1).
    assert (D1 : d1 = skip_bits d0 tl) by (revert RB1; unfold read_bits; destruct (look_bits d0 tl); cbn; congruence).
    pose proof (RF_huf_fdw_pure.skip_ok bs d0 tl BOK0 ltac:(lia) ltac:(lia)) as (BOK1 & _). rewrite <- D1 in BOK1.
    pose proof RESOK as RES. unfold decompress_usingDTable in RES. rewrite EI in RES. cbn [bind] in RES. rewrite RB1 in RES. cbn [bind] in RES.
    destruct (reload_dstream bs d1) as [[st1 d1r]|e1| |] eqn:R1; cbn [bind] in RES; try contradiction.
    2: { revert R1; unfold reload_dstream, readLE64; repeat match goal with |- context [if ?c then _ else _] => destruct c end;
         cbn; try discriminate; intros; discriminate. }
    pose proof (RF_huf_fdw_pure.reload_facts2 bs d1 st1 d1r BY BOK1 R1) as (BOK1r & _).
    destruct (read_bits_okD d1r tl ltac:(lia)) as (v2 & d2 & RB2). rewrite RB2 in RES. cbn [bind] in RES.
    destruct (reload_dstream bs d2) as [[st2 d2r]|e2| |] eqn:R2; cbn [bind] in RES; try contradiction.
    2: { revert R2; unfold reload_dstream, readLE64; repeat match goal with |- context [if ?c then _ else _] => destruct c end;
         cbn; try discriminate; intros; discriminate. }
    pose proof (rw_cells_split_CB _ _ _ [] 72 j48 [] [16%nat; 16%nat; 40%nat] FOBJ eq_refl) as FO2; cbn [app mk_CB_cells] in FO2.
    pose proof (rw_cells_mid _ _ _ [CB 16 (firstn 16 j48)] _ _ FO2) as DS2. cbn [cells_size csize Nat.add] in DS2.
    replace (SPAf SPV + 80 + Z.of_nat 16) with (SPAf SPV + 96) in DS2 by lia.
    pose proof (rw_cells_mid _ _ _ [] _ _ FO2) as DS1. cbn [cells_size csize Z.of_nat] in DS1. rewrite Z.add_0_r in DS1.
    eapply rw_cells_transport in DS2; [| exact MU1 | exact WM1 | cbn; unfold ABIT_INIT_STACK; lia].
    eapply rw_cells_transport in DS1; [| exact MU1 | exact WM1 | cbn; unfold ABIT_INIT_STACK; lia].
    pose proof fse_init_dstate_proofA as IDS. unfold fse_init_dstate_stmtA in IDS.
    zstep. zstep. zstep. zstep.
    eapply evtF_cut.
    { eapply IDS with (DS := SP1 + 96) (BD := SP1 + 112) (DT := DT) (S := S0) (tl := tl) (bs := bs) (d := d0) (jp := jp)
                      (v := v1) (d1 := d1) (st := st1) (d2 := d1r) (lo := lo);
        first [ exact DS2 | exact CELLS | exact SRC1 | exact BOK0 | exact RB1 | exact R1 | exact MI1 | exact STK1
              | rewrite unsigned_lit by lia; exact STK1 | sd_ids_side MU1 WM1 ]. }
    intros ms' (u0 & u1 & u2 & b0 & b1 & b2 & b3 & b4 & b5 & b6 & b7 & u3 & u4 & u5 & u6 & jp2 & m2 & -> & MU2 & WM2 & MI2 & STK2 & DSC1 & BDC1).
    rewrite unsigned_lit in MU2, STK2 by lia. unfold AFSE_INIT_STACK in MU2.
    sd_retlit.
    assert (MU12 : munch [(SP1 - ABIT_INIT_STACK, SP1); (SP1 + 80, SP1 + 152)] m0 m2).
    { eapply munch_trans; (eapply munch_weaken; [| first [exact MU1 | exact MU2]]); unfold sub_fp; intros x Hx; cbn [outside] in Hx |- *;
      unfold ABIT_INIT_STACK in *; destruct Hx as (H1 & H2 & _); repeat split; lia. }
    assert (WM12 : wmono bsegs m0 m2) by (eapply wmono_trans; [exact WM1 | exact WM2]).
    assert (SRC2 : bytes_at bsegs m2 S0 (map (Z_to_bv 8) bs)).
    { eapply bytes_at_transport; [exact SRC | exact MU12 | rewrite length_map; cbn; unfold ABIT_INIT_STACK; lia]. }
    eapply rw_cells_transport in DS1; [| exact MU2 | exact WM2 | cbn; lia].
    zstep. zstep. zstep. zstep.
    eapply evtF_cut.
    { eapply IDS with (DS := SP1 + 80) (BD := SP1 + 112) (DT := DT) (S := S0) (tl := tl) (bs := bs) (d := d1r) (jp := jp2)
                      (v := v2) (d1 := d2) (st := st2) (d2 := d2r) (lo := lo);
        first [ exact DS1 | exact BDC1 | exact SRC2 | exact BOK1r | exact RB2 | exact R2 | exact MI2 | exact STK2
              | rewrite unsigned_lit by lia; exact STK2 | sd_ids_side MU12 WM12 ]. }
    intros ms' (u0' & u1' & u2' & c0 & c1 & c2 & c3 & c4 & c5 & c6 & c7 & u3' & u4' & u5' & u6' & jp3 & m3 & -> & MU3 & WM3 & MI3 & STK3 & DSC2 & BDC2).
    rewrite unsigned_lit in MU3, STK3 by lia. unfold AFSE_INIT_STACK in MU3.
    sd_retlit.
    eapply (KIDS m3 jp3 v1 v2 st1 st2 d1 d1r d2 d2r); try eassumption.
    - eapply munch_trans; [eapply munch_weaken; [| exact MU12] | eapply munch_weaken; [| exact MU3]]; unfold sub_fp; intros x Hx;
      cbn [outside] in Hx |- *; unfold ABIT_INIT_STACK in *; destruct Hx as (H1 & H2 & H3 & _); repeat split; lia.
    - eapply wmono_trans; [exact WM12 | exact WM3].
    - eapply bytes_at_transport; [exact SRC2 | exact MU3 | rewrite length_map; cbn; lia].
    - eapply rw_cells_transport; [exact DSC1 | exact MU3 | exact WM3 | cbn; lia].
  Qed.

  (* [comment removed for export] *)
  Lemma sdA_init : forall (x1 x5 x6 x7 x10 x11 x13 x14 x15 x16 x17 x22 x23 x24 x25 x28 x29 x30 x31 : word),
