                     a1 a2 a3 a4 a5 a6 a7 (Z_to_bv 64 (Z.shiftr FF 3 + 2147450880))
                     (Z_to_bv 64 (DST + dcap - 3)) (Z_to_bv 64 DT) (Z_to_bv 64 (DST + dcap)) x22 x23 x24 x25
                     (Z_to_bv 64 S0) (Z_to_bv 64 2147450880) t3 t4 t5 t6)
                FR (Z_to_bv 64 0x98698) fc None m3 (seg_rom bsegs))) ->
    evtF bsegs RNG Q
      (MS (mkR x1 (Z_to_bv 64 SP1) gp tp x5 x6 x7 (Z_to_bv 64 SPV) (Z_to_bv 64 SP1) x10
               x11 (Z_to_bv 64 (zlen bs)) x13 x14 x15 x16 x17 (Z_to_bv 64 (Z.shiftr FF 3 + 2147450880))
               (Z_to_bv 64 (DST + dcap - 3)) (Z_to_bv 64 DT) (Z_to_bv 64 (DST + dcap)) x22 x23 x24 x25
               (Z_to_bv 64 S0) (Z_to_bv 64 2147450880) x28 x29 x30 x31)
          FR (Z_to_bv 64 0x98664) fc None m0 (seg_rom bsegs)).
  Proof.
    intros x1 x5 x6 x7 x10 x11 x13 x14 x15 x16 x17 x22 x23 x24 x25 x28 x29 x30 x31 KC.
    apply sdA_bit. intros d0 jp m1 ra t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 EI BZ MU1 WM1 MI1 STK1 SRC1 CELLS.
    eapply sdA_ids; try eassumption.
    intros. eapply KC; eassumption.
  Qed.

  (* [comment removed for export] *)
  Lemma sdA_ovf : forall m3 jp3 v1 v2 st1 st2 d0 d1 d1r d2 d2r (ra t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 x22 x23 x24 x25 t3 t4 t5 t6 : word),
          init_dstream bs = Ok d0 ->
          read_bits d0 tl = Ok (v1, d1) -> reload_dstream bs d1 = Ok (st1, d1r) ->
          read_bits d1r tl = Ok (v2, d2) -> reload_dstream bs d2 = Ok (st2, d2r) ->
          munch W0 m0 m3 -> wmono bsegs m0 m3 -> mem_inv bsegs m3 -> stk bsegs m3 lo SP1 ->
          rw_cells bsegs m3 (SP1 + 80) [C8 (Z_to_bv 64 v2); C8 (Z_to_bv 64 (DT + 4))] ->
          rw_cells bsegs m3 (SP1 + 96) [C8 (Z_to_bv 64 v1); C8 (Z_to_bv 64 (DT + 4))] ->
          rw_cells bsegs m3 (SP1 + 112) (bitdz_cellsA S0 d2r jp3) ->
          0 <= bd_bits d2r < 2^30 -> 64 < bd_bits d2r ->
          evtF bsegs RNG Q
            (MS (mkR ra (Z_to_bv 64 SP1) gp tp t0 t1 t2 (Z_to_bv 64 SPV) (Z_to_bv 64 SP1) a0
                     a1 a2 a3 a4 a5 a6 a7 (Z_to_bv 64 (Z.shiftr FF 3 + 2147450880))
                     (Z_to_bv 64 (DST + dcap - 3)) (Z_to_bv 64 DT) (Z_to_bv 64 (DST + dcap)) x22 x23 x24 x25
                     (Z_to_bv 64 S0) (Z_to_bv 64 2147450880) t3 t4 t5 t6)
                FR (Z_to_bv 64 0x98698) fc None m3 (seg_rom bsegs)).
  Proof.
    intros m3 jp3 v1 v2 st1 st2 d0 d1 d1r d2 d2r ra t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 x22 x23 x24 x25 t3 t4 t5 t6
      EI RB1 R1 RB2 R2 MU3 WM3 MI3 STK3 DSC2 DSC1 BDC BB B64.
    pose proof (spaf_props SPV SP16) as (SPAB & SPA32). pose proof LO as LO'. unfold DEC_STACK in LO'.
    pose proof (ablk_lin _ _ HDST) as LDS. pose proof ATOP_range as ATR. unfold ATOP_MIN, ATOP_MAX in ATR.
    assert (DE : decompress_usingDTable bs d dcap false = Err ZSTD_error_corruption_detected).
    { unfold decompress_usingDTable. rewrite EI. cbn [bind]. rewrite RB1. cbn [bind]. rewrite R1. cbn [bind].
      rewrite RB2. cbn [bind]. rewrite R2. cbn [bind]. unfold reload_dstream at 1.
      replace (64 <? bd_bits d2r) with true by (symmetry; apply Z.ltb_lt; lia). reflexivity. }
    pose proof BDC as BDC0. unfold bitdz_cellsA in BDC.
    repeat zstep.
    rewrite sx32_small; [| first [ lia | rewrite unsigned_lit by lia; lia ]].
    replace (negb (bv_ltu (Z_to_bv 64 64) (Z_to_bv 64 (bd_bits d2r)))) with false by
      (symmetry; rewrite bv_ltu_Z, !Z_to_bv_unsigned; unfold bv_wrap, bv_modulus; cbn [Z.of_N];
       rewrite !Z.mod_small by lia; apply Bool.negb_false_iff, Z.ltb_lt; lia).
    cbv iota. do 4 zstep.
    try replace (Z_to_bv 64 (-20)) with (Z_to_bv 64 (2^64 - ZSTD_error_corruption_detected))
      by (apply Z_to_bv_eqm; unfold ZSTD_error_corruption_detected; reflexivity).
    assert (FM80 : rw_cells bsegs m3 (SP1 + 80) [CB 72 (cells_bytes (([C8 (Z_to_bv 64 v2); C8 (Z_to_bv 64 (DT + 4))]
                   ++ [C8 (Z_to_bv 64 v1); C8 (Z_to_bv 64 (DT + 4))]) ++ bitdz_cellsA S0 d2r jp3))]).
    { pose proof (rw_cells_cat _ _ _ _ _ _ DSC2 DSC1 ltac:(cbn; lia)) as C1.
      pose proof (rw_cells_cat _ _ _ _ _ _ C1 BDC0 ltac:(cbn; lia)) as C2.
      assert (C2' : rw_cells bsegs m3 (SP1 + 80) ([] ++ (([C8 (Z_to_bv 64 v2); C8 (Z_to_bv 64 (DT + 4))]
                   ++ [C8 (Z_to_bv 64 v1); C8 (Z_to_bv 64 (DT + 4))]) ++ bitdz_cellsA S0 d2r jp3) ++ [])) by (rewrite app_nil_r; exact C2).
      exact (rw_cells_merge _ _ _ _ _ _ C2'). }
    eapply (K m3 (2^64 - ZSTD_error_corruption_detected)).
    - exact MU3.
    - exact WM3.
    - exact MI3.
    - exact STK3.
    - exact FM80.
    - eapply rw_cells_transport; [exact FC32 | exact MU3 | exact WM3 | cbn; lia].
    - rewrite DE. unfold dresA. split; [reflexivity | unfold ZSTD_error_corruption_detected; lia].
    - unfold ZSTD_error_corruption_detected; lia.
  Qed.
  Ltac sd_br b := lazymatch goal with |- evtF _ _ _ (MS _ _ (if ?c then _ else _) _ _ _ _) =>
    replace c with b; [cbv iota | symmetry; rewrite ?bv_ltu_Z, ?bv_eqb_Z, ?Z_to_bv_unsigned; unfold bv_wrap, bv_modulus; cbn [Z.of_N];
      first [apply Z.ltb_ge | apply Z.ltb_lt | apply Z.eqb_eq | apply Z.eqb_neq
            | apply Bool.negb_true_iff, Z.ltb_ge | apply Bool.negb_false_iff, Z.ltb_lt
            | apply Bool.negb_true_iff, Z.eqb_neq | apply Bool.negb_false_iff, Z.eqb_eq]; Z.div_mod_to_equations; lia] end.
  Ltac sd_appW := unfold appW; pose proof HDST as HDa; unfold ablk in HDa; pose proof atop_range as ATRa; pose proof BOT as BOTa;
    repeat (apply Forall_cons; [cbn [fst snd]; unfold KHIGH, KLOW, AIMG_HI, KLS in *;
      first [right; lia | destruct HDa as [HDa|HDa]; [left|right]; lia] |]); apply Forall_nil.
  Ltac sd_sub := let x := fresh "x" in let HX := fresh "HX" in
    intros x HX; cbn [outside] in HX |- *; pose proof LO as LOs; unfold DEC_STACK in LOs; lia.

  (* [comment removed for export] *)
  Lemma sdA_rbok : forall d0 t v d', bitd_ok bs d0 -> 0 <= t <= 12 -> bd_bits d0 < 2^29 -> read_bits d0 t = Ok (v, d') ->
    bitd_ok bs d' /\ bd_bits d' = bd_bits d0 + t.
  Proof.
    intros d0 t v d' OK T B RB. pose proof OK as (Oc & Ob & Op & Op8 & Oz & Ozr).
    rewrite (RF_huf_fdw_pure.rb_facts d0 t v d' T ltac:(lia) RB). unfold bitd_ok. cbn [bd_cont bd_bits bd_ptr bd_zero].
    repeat split; try lia; first [exact Oz | (intros HZ; specialize (Ozr HZ); lia)].
  Qed.

  Notation SBI pc mm x1 x5 x6 x7 x10 x11 x12 x13 x14 x15 x16 x17 x22 x23 x24 x25 x28 x29 x30 x31 :=
    (MS (mkR x1 (Z_to_bv 64 SP1) gp tp x5 x6 x7 (Z_to_bv 64 SPV) (Z_to_bv 64 SP1) x10
             x11 x12 x13 x14 x15 x16 x17 (Z_to_bv 64 (Z.shiftr FF 3 + 2147450880))
             (Z_to_bv 64 (DST + dcap - 3)) (Z_to_bv 64 DT) (Z_to_bv 64 (DST + dcap)) x22 x23 x24 x25
             (Z_to_bv 64 S0) (Z_to_bv 64 2147450880) x28 x29 x30 x31)
        FR (Z_to_bv 64 pc) fc None mm (seg_rom bsegs)).
  Notation SDPRE d0 v1 d1 st1 d1r v2 d2 st2 d2r :=
    (init_dstream bs = Ok d0 /\ read_bits d0 tl = Ok (v1, d1) /\ reload_dstream bs d1 = Ok (st1, d1r) /\
     read_bits d1r tl = Ok (v2, d2) /\ reload_dstream bs d2 = Ok (st2, d2r)).
  Notation SDMEM m3 v1 v2 := (munch W0 m0 m3 /\ wmono bsegs m0 m3 /\ mem_inv bsegs m3 /\ stk bsegs m3 lo SP1 /\
     bytes_at bsegs m3 S0 (map (Z_to_bv 8) bs) /\
     rw_cells bsegs m3 (SP1 + 80) [C8 (Z_to_bv 64 v2); C8 (Z_to_bv 64 (DT + 4))] /\
     rw_cells bsegs m3 (SP1 + 96) [C8 (Z_to_bv 64 v1); C8 (Z_to_bv 64 (DT + 4))]).

  Definition sdA_KC (x22 x23 x24 x25 : word) : Prop :=
    forall m3 jp3 v1 v2 st1 st2 d0 d1 d1r d2 d2r (ra t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 : word),
      init_dstream bs = Ok d0 ->
      read_bits d0 tl = Ok (v1, d1) -> reload_dstream bs d1 = Ok (st1, d1r) ->
      read_bits d1r tl = Ok (v2, d2) -> reload_dstream bs d2 = Ok (st2, d2r) ->
      munch W0 m0 m3 -> wmono bsegs m0 m3 -> mem_inv bsegs m3 -> stk bsegs m3 lo SP1 ->
      bytes_at bsegs m3 S0 (map (Z_to_bv 8) bs) ->
      rw_cells bsegs m3 (SP1 + 80) [C8 (Z_to_bv 64 v2); C8 (Z_to_bv 64 (DT + 4))] ->
      rw_cells bsegs m3 (SP1 + 96) [C8 (Z_to_bv 64 v1); C8 (Z_to_bv 64 (DT + 4))] ->
      rw_cells bsegs m3 (SP1 + 112) (bitdz_cellsA S0 d2r jp3) ->
      evtF bsegs RNG Q (SBI 0x98698 m3 ra t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 x22 x23 x24 x25 t3 t4 t5 t6).

  Notation sdA_K2936 := (sdm_K2936 RNG Q m0 SPV FF DST dcap S0 DT lo bs d gp tp FR fc).

  Definition sdA_K2928 (x22 x23 x24 x25 : word) : Prop :=
    forall m3 d0 v1 d1 st1 d1r v2 d2 st2 d2r jp (r1 t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 : word),
      SDPRE d0 v1 d1 st1 d1r v2 d2 st2 d2r -> bitd_ok bs d2r -> bd_bits d2r <= 64 -> bd_zero d2r = false -> 8 <= bd_ptr d2r ->
      SDMEM m3 v1 v2 -> rw_cells bsegs m3 (SP1 + 112) (bitdz_cellsA S0 d2r jp) ->
      evtF bsegs RNG Q (SBI 0x98cd0 m3 r1 t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 x22 x23 x24 x25 t3 t4 t5 t6).

  Definition sdA_K1376 (x22 x23 x24 x25 : word) : Prop :=
    forall m3 d0 v1 d1 st1 d1r v2 d2 st2 d2r jp (r1 t0 t1 t2 a3 a5 a6 a7 t3 t4 t5 t6 : word),
      SDPRE d0 v1 d1 st1 d1r v2 d2 st2 d2r -> bitd_ok bs d2r -> bd_bits d2r <= 64 -> bd_zero d2r = false -> 0 < bd_ptr d2r < 8 ->
      SDMEM m3 v1 v2 -> rw_cells bsegs m3 (SP1 + 112) (bitdz_cellsA S0 d2r jp) ->
      evtF bsegs RNG Q (SBI 0x986c0 m3 r1 t0 t1 t2 (Z_to_bv 64 (S0 + 8)) (Z_to_bv 64 (bd_bits d2r)) (Z_to_bv 64 (S0 + bd_ptr d2r))
                         a3 (Z_to_bv 64 S0) a5 a6 a7 x22 x23 x24 x25 t3 t4 t5 t6).

  (* [comment removed for export] *)
  Lemma sdA_split : forall (x22 x23 x24 x25 : word),
    sdA_K2928 x22 x23 x24 x25 -> sdA_K1376 x22 x23 x24 x25 -> sdA_K2936 x22 x23 x24 x25 -> sdA_KC x22 x23 x24 x25.
  Proof.
    intros x22 x23 x24 x25 KR KP KE m3 jp3 v1 v2 st1 st2 d0 d1 d1r d2 d2r ra t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6
      EI RB1 R1 RB2 R2 MU3 WM3 MI3 STK3 SRC3 DSC2 DSC1 BDC.
    pose proof (spaf_props SPV SP16) as (SPAB & SPA32). pose proof atop_range as ATR. pose proof LO as LO'. unfold DEC_STACK in LO'.
    pose proof (ablk_lin _ _ HS0) as HS0l.
    pose proof (RF_huf_fdw_pure.init_facts bs d0 BY EI) as (OK0 & B0 & _).
    pose proof (sdA_rbok d0 tl v1 d1 OK0 ltac:(lia) ltac:(lia) RB1) as (OK1 & BB1).
    pose proof (RF_huf_fdw_pure.reload_facts2 bs d1 st1 d1r BY OK1 R1) as (OK2 & BB2 & _).
    pose proof (sdA_rbok d1r tl v2 d2 OK2 ltac:(lia) ltac:(lia) RB2) as (OK3 & BB3).
    pose proof (RF_huf_fdw_pure.reload_facts2 bs d2 st2 d2r BY OK3 R2) as (OK4 & BB4 & _ & Z4 & O4).
    pose proof OK4 as (O4c & O4b & O4p & O4p8 & O4z & _).
    destruct (Z.leb_spec (bd_bits d2r) 64) as [B4|B4].
    2: { eapply sdA_ovf; [exact EI | exact RB1 | exact R1 | exact RB2 | exact R2 | exact MU3 | exact WM3 | exact MI3 | exact STK3
                          | exact DSC2 | exact DSC1 | exact BDC | lia | lia]. }
    assert (B3 : bd_bits d2 <= 64).
    { destruct (Z.leb_spec (bd_bits d2) 64) as [|G]; [lia|]. destruct (O4 G) as [_ ->]. cbn [bd_bits] in B4. lia. }
    destruct (Z4 B3) as [BZ4 _].
    pose proof (conj EI (conj RB1 (conj R1 (conj RB2 R2)))) as FP.
    pose proof (conj MU3 (conj WM3 (conj MI3 (conj STK3 (conj SRC3 (conj DSC2 DSC1)))))) as FM3.
    pose proof BDC as BD2'. unfold bitdz_cellsA in BD2'. rewrite BZ4 in BD2'. cbv iota in BD2'.
    pose proof (ablk_lin _ _ HDST) as LDS. pose proof FC32 as FC3. eapply rw_cells_transport in FC3; [| exact MU3 | exact WM3 | cbn; lia].
    repeat zstep.
    rewrite sx32_small; [| first [ lia | rewrite unsigned_lit by lia; lia ]].
    sd_br true. repeat zstep.
    destruct (Z.leb_spec 8 (bd_ptr d2r)) as [P8|P8].
    - sd_br true. eapply KR; [exact FP | exact OK4 | exact B4 | exact BZ4 | exact P8 | exact FM3 | exact BDC].
    - sd_br false. repeat zstep.
      destruct (Z.eqb_spec (bd_ptr d2r) 0) as [P0|P0].
      + sd_br true.
        eapply (KE m3 d0 v1 d1 st1 d1r v2 d2 st2 d2r (if bd_bits d2r <? 64 then EndOfBuffer else Completed) d2r jp3);
          [exact FP | | destruct (bd_bits d2r <? 64); reflexivity | exact OK4 | exact B4 | exact BZ4 | exact FM3 | exact BDC].
        unfold reload_dstream. replace (64 <? bd_bits d2r) with false by (symmetry; apply Z.ltb_ge; lia).
        replace (8 <=? bd_ptr d2r) with false by (symmetry; apply Z.leb_gt; lia). rewrite P0. reflexivity.
      + sd_br false. eapply KP; [exact FP | exact OK4 | exact B4 | exact BZ4 | lia | exact FM3 | exact BDC].
  Qed.

  (* [comment removed for export] *)
  Lemma sdA_reload : forall (x22 x23 x24 x25 : word), sdA_K2936 x22 x23 x24 x25 -> sdA_K2928 x22 x23 x24 x25.
  Proof.
    intros x22 x23 x24 x25 KE m3 d0 v1 d1 st1 d1r v2 d2 st2 d2r jp r1 t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6
      FP OK4 B4 BZ4 P8 FM3 BD2.
    pose proof (spaf_props SPV SP16) as (SPAB & SPA32). pose proof atop_range as ATR. pose proof LO as LO'. unfold DEC_STACK in LO'.
    pose proof (ablk_lin _ _ HS0) as HS0l. pose proof (ablk_lin _ _ HDST) as LDS.
    pose proof FM3 as (MW3 & WM3 & MI3 & STK3 & SRC3 & DSC2 & DSC1).
    pose proof OK4 as (O4c & O4b & O4p & O4p8 & O4z & _).
    assert (Q8 : bd_ptr d2r + 8 <= zlen bs) by lia.
    pose proof BD2 as BD3. unfold bitdz_cellsA in BD3. rewrite BZ4 in BD3. cbv iota in BD3.
    assert (UBD : unpoisoned m3 (SP1 + 112) (SP1 + 112 + 40)).
    { eapply unpoisoned_appW; [| exact MW3 | sd_appW | lia | lia].
      replace (SP1 + 112 + 40) with (SP1 + 152) by lia. exact (shclean_unpoisoned _ _ _ _ _ SHC). }
    zstep. zstep.
    eapply evtF_cut.
    { eapply (fse_reload_int_proofA RNG) with (BD := SP1 + 112) (S := S0) (bc := bd_bits d2r) (q := bd_ptr d2r) (bs := bs) (lo := lo).
      all: rewrite ?Z_to_bv_unsigned; unfold bv_wrap, bv_modulus, RELOADI_STACK; cbn [Z.of_N];
           rewrite ?(Z.mod_small (SPAf SPV)) by lia;
           first [ reflexivity | exact BD3 | exact SRC3 | exact BY | exact HS0 | exact MI3 | exact STK3 | exact UBD
                 | exact RS | exact RSs | exact RI | exact RISH | lia
                 | (eapply artcells_munchD; [exact RTC | exact MW3 | exact WM3 | cbn [aboveD]; unfold AIMG_HI in *; repeat split; lia])
                 | (eapply unpoisoned_appW; [exact USRC | exact MW3 | sd_appW | lia | lia])
                 | (eapply rng_sub; [exact RO | lia | lia])
                 | (eapply rng_sub; [exact RSTK | lia | lia])
                 | (eapply rng_sub; [exact ROs | |]; rewrite !shad_div; Z.div_mod_to_equations; lia) ]. }
    intros ms' (u0 & u1 & u2 & b1 & b2 & b3 & b4 & b5 & b6 & b7 & m4 & -> & MU4 & WM4 & MI4 & STK4 & RW4).
    unfold RELOADI_STACK in MU4. sd_retlit.
    set (d3 := mkBD (le64v bs (bd_ptr d2r - bd_bits d2r / 8)) (bd_bits d2r mod 8) (bd_ptr d2r - bd_bits d2r / 8) false).
    assert (RL3 : reload_dstream bs d2r = Ok (Unfinished, d3)).
    { unfold reload_dstream, d3. replace (64 <? bd_bits d2r) with false by (symmetry; apply Z.ltb_ge; lia).
      replace (8 <=? bd_ptr d2r) with true by (symmetry; apply Z.leb_le; lia).
      rewrite Z.shiftr_div_pow2 by lia. change (2^3) with 8.
      rewrite readLE64_ok by (Z.div_mod_to_equations; lia). cbn [bind].
      replace (Z.land (bd_bits d2r) 7) with (bd_bits d2r mod 8) by (symmetry; apply (Z.land_ones (bd_bits d2r) 3); lia).
      reflexivity. }
    pose proof (RF_huf_fdw_pure.reload_facts2 bs d2r Unfinished d3 BY OK4 RL3) as (OK5 & BB5 & _ & Z5 & _).
    destruct (Z5 B4) as [BZ5 OV5].
    assert (MW4 : munch W0 m0 m4) by (eapply munch_trans; [exact MW3 | eapply munch_weaken; [| exact MU4]; sd_sub]).
    eapply (KE m4 d0 v1 d1 st1 d1r v2 d2 st2 d2r Unfinished d3); [exact FP | exact RL3 | exact OV5 | exact OK5 | lia | exact BZ5 | | ].
    - split; [exact MW4|]. split; [exact (wmono_trans bsegs _ _ _ WM3 WM4)|]. split; [exact MI4|]. split; [exact STK4|].
      split; [| split].
      + eapply bytes_at_transport; [exact SRC3 | exact MU4 | cbn [disjoint_from]; rewrite length_map; lia].
      + eapply rw_cells_transport; [exact DSC2 | exact MU4 | exact WM4 | cbn; lia].
      + eapply rw_cells_transport; [exact DSC1 | exact MU4 | exact WM4 | cbn; lia].
    - unfold bitdz_cellsA, d3. cbn [bd_cont bd_bits bd_ptr bd_zero]. unfold reload_cellsA in RW4. exact RW4.
  Qed.

  (* [comment removed for export] *)
  Lemma sdA_chk : forall (x22 x23 x24 x25 : word), sdA_K1376 x22 x23 x24 x25 -> sdA_K2936 x22 x23 x24 x25 -> sdA_KC x22 x23 x24 x25.
  Proof. intros x22 x23 x24 x25 KP KE. exact (sdA_split x22 x23 x24 x25 (sdA_reload x22 x23 x24 x25 KE) KP KE). Qed.

  Lemma sdp_sh0 : forall (m : amem) l h a, unpoisoned m l h -> l <= a -> 8 * (a / 8) + 8 <= h -> h <= KEND ->
    exists b, rw_cells bsegs m (Z.shiftr a 3 + ASHOFF) [C1 b] /\ Z.shiftr a 3 + ASHOFF + 1 <= KHIGH /\ sval b = 0.
  Proof.
    intros m l h a U L H K'.
    assert (A8 : Z.shiftr a 3 = a / 8) by (apply Z.shiftr_div_pow2; destruct U; lia).
    pose proof U as (U0 & U1 & U2).
    destruct (U2 (Z.shiftr a 3) ltac:(Z.div_mod_to_equations; lia) ltac:(rewrite A8; Z.div_mod_to_equations; lia)
               ltac:(rewrite A8; Z.div_mod_to_equations; lia)) as (b & MB & GB).
    exists b. split; [|split].
    - apply AProg_kit.c1_of_byte; [rewrite A8; unfold ASHOFF; Z.div_mod_to_equations; lia
                                 | rewrite A8; unfold ASHOFF, KEND in *; Z.div_mod_to_equations; lia |].
      rewrite Z.add_comm; exact MB.
    - apply AProg_kit.shad_lt_KHIGH; Z.div_mod_to_equations; lia.
    - unfold gran_ok in GB. rewrite A8, Z.min_l in GB by lia. destruct GB as [G0|G0]; [exact G0 | lia].
  Qed.
  Ltac sdp_zlit x := lazymatch x with 0%Z => idtac | 1%Z => idtac end.
  Ltac sdp_zx := repeat match goal with
    | |- context [Z.lxor ?x ?y <? 1] =>
        replace (Z.lxor x y <? 1) with false by
          (symmetry; apply Z.ltb_ge;
           assert (0 <= Z.lxor x y) by (apply (proj2 (Z.lxor_nonneg x y)); split; intro; Z.div_mod_to_equations; lia);
           assert (Z.lxor x y <> 0) by (rewrite Z.lxor_eq_0_iff; Z.div_mod_to_equations; lia); lia)
    | |- context [0 <? ?a] => replace (0 <? a) with true by (symmetry; apply Z.ltb_lt; Z.div_mod_to_equations; lia)
    | |- context [Z.lxor ?x ?y] => sdp_zlit x; sdp_zlit y; let v := eval vm_compute in (Z.lxor x y) in change (Z.lxor x y) with v
    | |- context [Z.land ?x ?M] =>
        replace (Z.land x M) with x by (symmetry; change M with (Z.ones 32); rewrite Z.land_ones by lia; apply Z.mod_small; Z.div_mod_to_equations; lia)
    end; cbn [Z.b2z Z.lxor].
  Ltac sdp_wk := repeat first [ zstep | sd_br true | sd_br false | progress sdp_zx ].

  Ltac sdp_at k := lazymatch goal with |- evtF _ _ _ (MS _ _ (Z_to_bv 64 ?p) _ _ _ _) =>
    let dd := eval vm_compute in (p - 0x98160) in constr_eq dd k end.
  Ltac sdp_to k := repeat (tryif sdp_at k then fail else first [ zstep | sd_br true | sd_br false | progress sdp_zx ]).

  Lemma sdp_rl : forall d2r nb, bitd_ok bs d2r -> bd_bits d2r <= 64 -> 0 < bd_ptr d2r < 8 -> 8 <= zlen bs ->
    ((0 <= bd_ptr d2r - bd_bits d2r / 8 /\ nb = bd_bits d2r / 8) \/ (bd_ptr d2r - bd_bits d2r / 8 < 0 /\ nb = bd_ptr d2r)) ->
    reload_dstream bs d2r = Ok (if bd_ptr d2r - bd_bits d2r / 8 <? 0 then EndOfBuffer else Unfinished,
