    rng RNG lo (SPAf SPV - lo) -> rng_aimg RNG -> rng_aimg_sh RNG ->
    (forall m1 rv (j48' : list byte) (y1 y5 y6 y7 y11 y12 y13 y14 y15 y16 y17 y19 y20 y21 y22 y23 y24 y25 y26 y27 y28 y29 y30 y31 : word),
